      const result=await api('advanced/assets/post-depreciation',{method:'POST',json:{depreciationLineId:line.id,operationKey:button.dataset.teghOperationKey,expectedSourceRevisionHash:line.sourceRevisionHash,expectedEntitlementRevision:Number(data.entitlementRevision||0)}});
      const message=result.alreadyPosted?'This occurrence was already posted; no duplicate journal was created.':`Depreciation posted once${result.voucher?.number?` as ${result.voucher.number}`:''}.`;
